	omu = &sync.Mutex{}
	block = func(ids ...uint64) {
		bmu.Lock()
		defer bmu.Unlock()
		for _, id := range ids {
			gates[id] = make(chan struct{})
		}
	}
	release = func(id uint64) {
		bmu.Lock()
		ch, ok := gates[id]
		bmu.Unlock()
		if ok {
			close(ch)
		}
	}
	s.compute = func(id uint64, inputs []int64, seed int64, canceled func() bool) (int64, int64, string, bool) {
		started <- id
		bmu.Lock()
		ch := gates[id]
		bmu.Unlock()
