	waitStarted(t, started, head.ID)
	// up 排在 waiter 前面但会一直排队（重开后用闸门堵住它）。
	up := mustSubmit(t, s, SubmitRequest{Submitter: "a", RequestID: "up", Values: []int64{7}})
	waiter := mustSubmit(t, s, SubmitRequest{
