	}
	c, _ := s2.Get(cq.ID)
	if c.Status != StatusCanceled {
		t.Fatalf("cancel record wrong after reopen: %s", c.Status)
	}

	// 作业号续号，不复用。
	next := mustSubmit(t, s2, SubmitRequest{Submitter: "a", Values: []int64{1}})
	if next.ID <= cq.ID {
