	if len(onlyYi) != 1 || onlyYi[0].ID != yi.ID {
		t.Fatalf("10:00 range=%v, want only 乙(%d)", idList(onlyYi), yi.ID)
	}
	// 同一时刻 10:03 的丙、丁仍按接受顺序列出。
	tie, err := s2.List("a", atClock(10, 3), atClock(10, 3))
