// gateComputeOption 与 gateCompute 等价，但以 [Option] 形式在 [Open] 启动
// worker 之前装好计算钩子，避免重开后第一批排队作业在钩子装好前就跑完。
func gateComputeOption() (
	Option,
	chan uint64,
	func(ids ...uint64),
	func(id uint64),
	*[]uint64,
	*sync.Mutex,
) {
	started := make(chan uint64, 64)
	var bmu sync.Mutex
	gates := make(map[uint64]chan struct{})
	var ord []uint64
	omu := &sync.Mutex{}
	block := func(ids ...uint64) {
		bmu.Lock()
		defer bmu.Unlock()
		for _, id := range ids {
			gates[id] = make(chan struct{})
		}
	}
	release := func(id uint64) {
		bmu.Lock()
		ch, ok := gates[id]
		bmu.Unlock()
		if ok {
			select {
			case <-ch: // 已关闭
			default:
				close(ch)
			}
		}
	}
	hook := func(id uint64, inputs []int64, seed int64, canceled func() bool) (int64, int64, string, bool) {
		started <- id
		bmu.Lock()
		ch := gates[id]
		bmu.Unlock()
		if ch != nil {
			select {
			case <-ch:
			}
		}
		omu.Lock()
		ord = append(ord, id)
		omu.Unlock()
		return computeResult(inputs, seed, canceled)
	}
	opt := func(s *Store) { s.compute = hook }
	return opt, started, block, release, &ord, omu
}

func snapshotOrder(ord *[]uint64, omu *sync.Mutex) []uint64 {
	omu.Lock()
	defer omu.Unlock()
	return append([]uint64(nil), (*ord)...)
