	bing := mustSubmit(t, s, SubmitRequest{Submitter: "a", RequestID: "bing", Values: []int64{4}})
	ding := mustSubmit(t, s, SubmitRequest{Submitter: "a", RequestID: "ding", Values: []int64{5}})
	if err := s.Close(); err != nil {
		t.Fatal(err)
	}

