	s2, err := Open(dir, opt)
	if err != nil {
		t.Fatal(err)
	}
	defer s2.Close()

	waitStatus(t, s2, head.ID, StatusFailed) // 上次运行被中断
	wantOrder := []uint64{jia.ID, yi.ID, bing.ID, ding.ID}
	for _, id := range wantOrder {
		waitStatus(t, s2, id, StatusSucceeded)
	}
