		t.Fatalf("list ids=%v, want %v", gotIDs, wantOrder)
	}
	for i := range wantOrder {
		if gotIDs[i] != wantOrder[i] {
			t.Fatalf("list order=%v, want %v", gotIDs, wantOrder)
		}
